"""Собирает ядро бота и адаптеры каналов Time.

Запускать ИЗ ЭТОЙ ПАПКИ (`cd bot`): пути относительны рабочего каталога,
и реестр базы знаний в тестах берётся через `../executive-support/`.

На входе — Support Bot DD.json (build_dd_flow.py): из него берутся проверенные
узлы GitLab и модели с их credential'ами. Промпты берутся из prompts/*.md.
На выходе четыре файла:

  Support Bot Core.json      — КОНВЕЙЕР: роутер → чтение статей и DD → автор.
                               Вызывается по id, вход { question, mode },
                               выход — разобранная структура.
                               Узел «Trace» перед финалом собирает весь прогон
                               в один markdown: что выбрал роутер, что добрал
                               код, что реально доехало до автора и какие узлы
                               не запускались. Для разбора кейса: открыть
                               Execution → «Trace» → скопировать поле trace.
  Adapter Channel.json       — слушает hr-report-ask, пишет черновик в stonis_hakcs_2.
  Adapter Chat.json          — chatTrigger для ручного тестирования.
  Adapter DM.json            — личка с ботом, ответ в тот же диалог.
                               На время работы ядра вешает реакцию
                               :bully_work: и снимает её после ответа.

ГДЕ ЖИВЁТ ПРОМПТ
В prompts/router.md и prompts/author.md — источник правды. Сборщик вклеивает их
в узлы Router и Author, срезая HTML-комментарии для разработчика. В JSON промпт
руками не правится, и patch_prompt.py к ядру больше не относится: он патчит
промпт старого флоу Support Bot DD.json.

ПОЧЕМУ ЯДРО ОТДЕЛЬНО, А НЕ ТРИ ТРИГГЕРА В ОДНОМ ФЛОУ
Два триггера в одном воркфлоу n8n допускает, но AI Agent.text ссылался на
$('When chat message received'), а этого узла в выполнении от Time-триггера нет.
Главное же не в этом: тест в чате должен проверять ровно то, что работает
в канале. При общем ядре это свойство конструкции, а не дисциплины. Копия
промпта в трёх флоу разъезжается молча — ровно так же, как список полей,
скопированный из DD в статью.

ПОРЯДОК ИМПОРТА (четыре шага, каждый следующий нужен из-за статических id)
1. DD Lookup.json → импортировать, скопировать id из адресной строки
2. DD_SUBFLOW_ID=<id> python3 build_dd_flow.py
3. python3 build_time_flows.py → импортировать Support Bot Core.json → взять id
4. CORE_WORKFLOW_ID=<id> python3 build_time_flows.py → импортировать адаптеры

Без шага 2 ядро зовёт DD Lookup по плейсхолдеру и падает на «workflow not
found»; без шага 4 то же самое делают адаптеры с ядром. Обе ошибки осознанно
громкие: тихо неверная работа хуже.

Сборщик проверяет оба id на выходе и предупреждает, если остался плейсхолдер.

ПРОВЕРКА ПОСЛЕ ПРАВОК
  node test_pipeline.mjs   Code-ноды конвейера: план, мастера, материалы
  node test_adapters.mjs   разбор ответа, сборка сообщений, проводка
  node test_shapers.mjs    шейперы DD Lookup
"""
import json
import copy
import hashlib
import os
import re

SRC = "Support Bot DD.json"
DST_CORE = "Support Bot Core.json"
DST_CHANNEL = "Adapter Channel.json"
DST_CHAT = "Adapter Chat.json"
DST_DM = "Adapter DM.json"

# id ядра «Support Bot Core» в n8n — ПОДТВЕРЖДЁН, воркфлоу импортирован.
#
# Значение по умолчанию, а не плейсхолдер: id выдаёт n8n при импорте, и пока он
# жил только в переменной окружения, каждая пересборка без CORE_WORKFLOW_ID
# молча возвращала плейсхолдер — адаптер падал на «workflow not found». Та же
# причина, по которой записаны DD_SUBFLOW_ID здесь же и INGEST_ID в телеметрии.
#
# ВАЖНО: id принадлежит воркфлоу, а не его содержимому. Переимпорт ядра
# ПОВЕРХ существующего (Workflow → Import from File в уже открытом ядре) id
# сохраняет, и адаптеры пересобирать не нужно. Импорт ядра НОВЫМ воркфлоу
# даёт другой id — тогда CORE_WORKFLOW_ID=<новый> python3 build_time_flows.py
# и переимпорт адаптеров. Разница незаметна по виду флоу: старое ядро
# продолжает отвечать, просто без новых полей.
CORE_ID = os.environ.get("CORE_WORKFLOW_ID", "quV6Ec1hmobZefBX")

# Каналы Time. Имена подтверждены пользователем и артефактом выгрузки
# hr-report-ask-3-4-aug-2026.md. Задаются по имени (mode: name), как в примере
# Time examples.json, поэтому опечатка тихо приведёт к молчащему триггеру.
# Каналы задаются через окружение: добавить канал — это решение владельца
