WORK_EMOJI = "bully_work"

# ИМЕНА БОТА ДЛЯ РАСПОЗНАВАНИЯ @УПОМИНАНИЯ — СПИСОК, А НЕ ОДНО.
#
# Живой прогон 02.09: в канале написали «@Булли», и бот промолчал. Логин
